let customLoaderCheckInterval = null;

function ensureBirdLoaderStyle() {
  if (document.getElementById(CUSTOM_LOADER_STYLE_ID)) return;

  const style = document.createElement("style");
  style.id = CUSTOM_LOADER_STYLE_ID;
  style.textContent = `
    /* ===== TADa CUSTOM GIANT BIRD LOADER ===== */

    /* Hide default YouTube player spinner rotators */
    .ytp-spinner .ytp-spinner-container,
    .ytp-spinner .ytp-spinner-rotator,
    .ytp-spinner .ytp-spinner-message {
      display: none !important;
    }

    /* Custom Giant Bird Container */
    .tada-bird-spinner {
      position: absolute !important;
      top: 50% !important;
      left: 50% !important;
      transform: translate(-50%, -50%) !important;
      width: 72px !important;
      height: 72px !important;
      display: flex !important;
      align-items: center !important;
      justify-content: center !important;
      pointer-events: none !important;
      z-index: 20 !important;
    }

    .tada-bird-loader-svg {
      width: 100% !important;
      height: 100% !important;
      overflow: visible !important;
      filter: drop-shadow(0 2px 10px rgba(0, 0, 0, 0.85)) drop-shadow(0 0 6px var(--tada-progress-color, rgba(232, 147, 12, 0.5))) !important;
    }

    .tada-bird-loader-svg path {
      stroke: var(--tada-progress-color, #E8930C) !important;
      stroke-width: 0.7px !important;
      animation: tadaBirdDashArray 4s ease-in-out infinite,
                 tadaBirdDashOffset 4s linear infinite !important;
    }

    @keyframes tadaBirdDashArray {
      0% {
        stroke-dasharray: 0 1 359 0;
      }
      50% {
        stroke-dasharray: 0 359 1 0;
      }
      100% {
        stroke-dasharray: 359 1 0 0;
      }
    }

    @keyframes tadaBirdDashOffset {
      0% {
        stroke-dashoffset: 365;
      }
      100% {
        stroke-dashoffset: 5;
      }
    }
  `;
  (document.head || document.documentElement).appendChild(style);
}

function ensureBirdLoaderDom() {
  if (!currentSettings.customLoader) {
    removeCustomLoader();
    return;
  }

  ensureBirdLoaderStyle();

  const spinners = document.querySelectorAll(".ytp-spinner");
  if (!spinners.length) return;

  spinners.forEach((spinner) => {
    let birdEl = spinner.querySelector(".tada-bird-spinner");
    if (!birdEl) {
      birdEl = document.createElement("div");
      birdEl.className = "tada-bird-spinner";
      birdEl.innerHTML = BIRD_LOADER_SVG_MARKUP;
      spinner.appendChild(birdEl);
    }
  });
}

function removeCustomLoader() {
  document.getElementById(CUSTOM_LOADER_STYLE_ID)?.remove();
  document.querySelectorAll(".tada-bird-spinner").forEach((el) => el.remove());
}

function startCustomLoaderCheck() {
  if (customLoaderCheckInterval) {
    clearInterval(customLoaderCheckInterval);
    customLoaderCheckInterval = null;
  }

  ensureBirdLoaderDom();

  let count = 0;
  customLoaderCheckInterval = setInterval(() => {
    count++;
    if (isWatchPage()) {
      ensureBirdLoaderDom();
    }
    if (count > 25 && document.querySelector(".tada-bird-spinner")) {
      clearInterval(customLoaderCheckInterval);
      customLoaderCheckInterval = null;
    }
  }, 350);
}

function applyCustomLoaderSetting() {
  if (currentSettings.customLoader) {
    ensureBirdLoaderStyle();
    startCustomLoaderCheck();
  } else {
    removeCustomLoader();
  }
}



